 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            colors = {grid[y][x] for y, x in cells}
            components.append((len(colors), cells))
    _, cells = max(components, key=lambda item: item[0])
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)
    return [row[c0:c1+1] for row in grid[r0:r1+1]]
